import UIKit
import UniformTypeIdentifiers

@objc(ShareController) final class ShareController: CheckerController {
    private var load: Progress?, received = false
    override func viewDidLoad() {
        shareMode = true; super.viewDidLoad(); status.text = "Loading selected text…"
        let items = extensionContext?.inputItems.compactMap { $0 as? NSExtensionItem } ?? []
        let providers = items.flatMap { $0.attachments ?? [] }.filter { $0.hasItemConformingToTypeIdentifier(UTType.plainText.identifier) }
        guard providers.count == 1 else { status.text = "Choose one plain-text selection to check."; return }
        load = providers[0].loadFileRepresentation(forTypeIdentifier: UTType.plainText.identifier) { [weak self] value, error in
            // This copy is valid only inside the provider callback. No path is retained.
            let text = error == nil ? value.flatMap { try? SharedText.read($0) } : nil
            DispatchQueue.main.async {
                guard let self, !self.received else { return }; self.received = true
                guard let text else {
                    self.status.text = "That selection is unavailable or too long. Choose plain text up to 20,000 characters."; return
                }
                self.input.text = text; self.status.text = "Review the selection, then choose Check with PS."
            }
        }
        DispatchQueue.main.asyncAfter(deadline: .now() + 10) { [weak self] in
            guard let self, !self.received else { return }; self.received = true; self.load?.cancel()
            self.status.text = "The selection did not arrive. Cancel and try another plain-text selection."
        }
    }
    override func viewDidDisappear(_ animated: Bool) { load?.cancel(); received = true; super.viewDidDisappear(animated) }
    override func clear() { load?.cancel(); received = true; super.clear() }
}

